/**
 * A multi-step form header: the steps with the current one marked (aria-current step), and the current step's
 * text with back and next buttons. Axes: layout (horizontal, vertical), marker (number, icon), summary (show,
 * hide).
 */
import { Fragment, type ReactNode } from "react";
import { Button } from "../primitives/button/button";
import { Group } from "../primitives/group/group";
import { IconBadge } from "../primitives/iconbadge/iconbadge";
import { List } from "../primitives/list/list";
import { ListItem } from "../primitives/list/list-item";
import { LucideIcon } from "../primitives/lucide-icon/lucide-icon";
import { Stack } from "../primitives/stack/stack";
import { Text } from "../primitives/text/text";
import { Title } from "../primitives/title/title";
import { SectionFrame } from "../components/section-frame";
import { cn, tpl } from "../utils";
import type { Step } from "./steps-list.types";

export type StepperProps = {
  id: string;
  title: string;
  steps: Step[];
  current?: number;
  stepLabel: string;
  back: string;
  next: string;
  layout?: "horizontal" | "vertical";
  marker?: "number" | "icon";
  summary?: "show" | "hide";
};

export function Stepper({
  id,
  title,
  steps,
  current = 2,
  stepLabel,
  back,
  next,
  layout = "horizontal",
  marker = "number",
  summary = "show",
}: StepperProps) {
  return (
    <SectionFrame id={id} title={title} measure="3xl">
      <Stack gap="6" align="stretch" data-testid="stepper">
        <Text size="sm" className="text-muted-foreground">
          {tpl(stepLabel, current, (steps?.length ?? 0))}
        </Text>
        <List
          tag="ol"
          className={cn(
            "m-0 flex list-none gap-4 p-0",
            (((layout as string) === "vertical") ? "flex-col" : "flex-col sm:flex-row")
          )}
          data-testid="items"
        >
          {(steps ?? []).map((s, i) => (
            <ListItem key={s.id}
              className="flex flex-1 items-center gap-4"
              data-testid="item"
              aria-current={(((i + 1) === current) ? "step" : undefined)}
            >
              <IconBadge
                variant={(((i + 1) < (current + 1)) ? "primary" : "outline")}
                size="sm"
                className={(((i + 1) < (current + 1)) ? "text-sm" : "text-sm text-muted-foreground")}
              >
                {((marker as string) === "icon") ? (
                  <LucideIcon name={s.icon} size={16} />
                ) : (
                  <Text size="sm" weight="bold">
                    {((i + 1) == null ? undefined : String((i + 1)))}
                  </Text>
                )}
              </IconBadge>
              <Text size="sm" weight={(((i + 1) === current) ? "bold" : "semibold")}>
                {s.title}
              </Text>
            </ListItem>
          ))}
        </List>
        {((summary as string) === "show") ? (
          <>
            {(steps ?? []).map((s, i) => (
              <Fragment key={s.id}>
                {((i + 1) === current) ? (
                  <Stack gap="2" className="rounded bg-card p-6 inset-ring inset-ring-border" data-testid="step-summary">
                    <Title as={3} size="xl" weight="bold">
                      {s.title}
                    </Title>
                    <Text size="sm" className="text-muted-foreground">
                      {s.text}
                    </Text>
                    <Group gap="2" className="pt-2">
                      <Button variant="outline" size="sm" type="button">
                        {back}
                      </Button>
                      <Button variant="default" size="sm" type="button">
                        {next}
                      </Button>
                    </Group>
                  </Stack>
                ) : null}
              </Fragment>
            ))}
          </>
        ) : null}
      </Stack>
    </SectionFrame>
  );
}
